from lib import *
LES = [
L("ident", "C", "Using trig identities", "การใช้เอกลักษณ์ตรีโกณ",
 [T("<b>Theorem.</b> For all real $x$, $A$, $B$: $$\\sin^{2}x=\\tfrac12(1-\\cos2x),\\quad \\cos^{2}x=\\tfrac12(1+\\cos2x),\\quad \\tan^{2}x=\\sec^{2}x-1\\ (\\cos x\\neq0),$$ $$\\sin A\\cos B=\\tfrac12\\big[\\sin(A+B)+\\sin(A-B)\\big],$$ $$\\cos A\\cos B=\\tfrac12\\big[\\cos(A-B)+\\cos(A+B)\\big],\\quad \\sin A\\sin B=\\tfrac12\\big[\\cos(A-B)-\\cos(A+B)\\big].$$",
    "<b>ทฤษฎีบท</b> สำหรับจำนวนจริง $x$, $A$, $B$ ทุกตัว: $$\\sin^{2}x=\\tfrac12(1-\\cos2x),\\quad \\cos^{2}x=\\tfrac12(1+\\cos2x),\\quad \\tan^{2}x=\\sec^{2}x-1\\ (\\cos x\\neq0),$$ $$\\sin A\\cos B=\\tfrac12\\big[\\sin(A+B)+\\sin(A-B)\\big],$$ $$\\cos A\\cos B=\\tfrac12\\big[\\cos(A-B)+\\cos(A+B)\\big],\\quad \\sin A\\sin B=\\tfrac12\\big[\\cos(A-B)-\\cos(A+B)\\big]$$"),
  T("<b>Corollary.</b> $\\int\\sin^{2}x\\,dx=\\dfrac{x}{2}-\\dfrac{\\sin2x}{4}+C$, and for an integer $k\\ge0$, $\\int\\sin^{2k+1}x\\,dx$ is a polynomial in $\\cos x$ (plus $C$); the same holds with $\\sin$ and $\\cos$ swapped.",
    "<b>บทแทรก</b> $\\int\\sin^{2}x\\,dx=\\dfrac{x}{2}-\\dfrac{\\sin2x}{4}+C$ และสำหรับจำนวนเต็ม $k\\ge0$ $\\int\\sin^{2k+1}x\\,dx$ เป็นพหุนามใน $\\cos x$ (บวก $C$) และสลับ $\\sin$ กับ $\\cos$ ได้เช่นกัน")],
 [S("Start from the compound-angle formulas (taken as known):", "เริ่มจากสูตรมุมประกอบ (ถือว่าทราบแล้ว):", "\\cos(A\\pm B)=\\cos A\\cos B\\mp\\sin A\\sin B,\\qquad \\sin(A\\pm B)=\\sin A\\cos B\\pm\\cos A\\sin B."),
  S("Put $A=B=x$ in the cosine formula and use $\\sin^{2}x+\\cos^{2}x=1$:", "แทน $A=B=x$ ในสูตร cos และใช้ $\\sin^{2}x+\\cos^{2}x=1$:", "\\cos2x=\\cos^{2}x-\\sin^{2}x=1-2\\sin^{2}x=2\\cos^{2}x-1,"),
  S("which rearranges to the first two identities. Dividing $\\sin^{2}x+\\cos^{2}x=1$ by $\\cos^{2}x\\neq0$ gives $\\tan^{2}x+1=\\sec^{2}x$.", "จัดรูปได้สองเอกลักษณ์แรก หาร $\\sin^{2}x+\\cos^{2}x=1$ ด้วย $\\cos^{2}x\\neq0$ ได้ $\\tan^{2}x+1=\\sec^{2}x$"),
  S("Adding $\\sin(A+B)$ and $\\sin(A-B)$ cancels the $\\cos A\\sin B$ terms; adding or subtracting the two cosine formulas gives the other two:", "บวก $\\sin(A+B)$ กับ $\\sin(A-B)$ พจน์ $\\cos A\\sin B$ หักล้างกัน และบวกหรือลบสูตร cos สองสูตรได้อีกสองเอกลักษณ์:", "\\sin(A+B)+\\sin(A-B)=2\\sin A\\cos B."),
  S("Corollary: integrate $\\tfrac12-\\tfrac12\\cos2x$ using lesson 5. For odd powers write", "บทแทรก: อินทิเกรต $\\tfrac12-\\tfrac12\\cos2x$ ด้วยบทที่ 5 สำหรับกำลังคี่เขียน", "\\sin^{2k+1}x=\\left(1-\\cos^{2}x\\right)^{k}\\sin x=\\sum_{j=0}^{k}\\binom{k}{j}(-1)^{j}\\cos^{2j}x\\,\\sin x,"),
  S("and each term integrates by lesson 7 (with $g=\\cos x$, $g'=-\\sin x$):", "และแต่ละพจน์อินทิเกรตด้วยบทที่ 7 (ให้ $g=\\cos x$, $g'=-\\sin x$):", "\\int\\cos^{2j}x\\sin x\\,dx=-\\frac{\\cos^{2j+1}x}{2j+1}+C.\\ \\blacksquare")],
 [X(r"\int_{0}^{\pi}\cos^{2}x\,dx", "pi/2", r"\frac{\pi}{2}", "cos(x)**2", ("d", "0", "pi"), [r"\cos^{2}x=\tfrac12(1+\cos2x)", r"\left[\tfrac{x}{2}+\tfrac{\sin2x}{4}\right]_{0}^{\pi}=\frac{\pi}{2}"]),
  X(r"\int\sin^{3}x\,dx", "-cos(x)+cos(x)^3/3", r"-\cos x+\frac{\cos^{3}x}{3}+C", "sin(x)**3", ("i", "0.2", "2"), [r"\sin^{3}x=\left(1-\cos^{2}x\right)\sin x", r"=-\cos x+\frac{\cos^{3}x}{3}+C"])],
 [P(r"\int_{0}^{\frac{\pi}{4}}\cos^{2}x\,dx", "pi/8+1/4", r"\frac{\pi}{8}+\frac14", "cos(x)**2", ("d", "0", "pi/4"), [r"\left[\tfrac{x}{2}+\tfrac{\sin2x}{4}\right]_{0}^{\frac{\pi}{4}}=\frac{\pi}{8}+\frac14"], "Use $\\cos^{2}x=\\tfrac12(1+\\cos2x)$.", "ใช้ $\\cos^{2}x=\\tfrac12(1+\\cos2x)$"),
  P(r"\int_{0}^{\frac{\pi}{2}}\sin3x\cos x\,dx", "1/2", r"\frac12", "sin(3*x)*cos(x)", ("d", "0", "pi/2"), [r"\sin3x\cos x=\tfrac12\left(\sin4x+\sin2x\right)", r"\tfrac12\left[-\tfrac{\cos4x}{4}-\tfrac{\cos2x}{2}\right]_{0}^{\frac{\pi}{2}}=\tfrac12\left(0+1\right)=\frac12"], "Product to sum: $\\sin A\\cos B$.", "ผลคูณเป็นผลบวก: $\\sin A\\cos B$"),
  P(r"\int_{0}^{\frac{\pi}{2}}\cos^{3}x\,dx", "2/3", r"\frac23", "cos(x)**3", ("d", "0", "pi/2"), [r"\cos^{3}x=\left(1-\sin^{2}x\right)\cos x", r"\left[\sin x-\tfrac{\sin^{3}x}{3}\right]_{0}^{\frac{\pi}{2}}=\frac23"], "Odd power: keep one $\\cos x$.", "กำลังคี่: เก็บ $\\cos x$ ไว้หนึ่งตัว"),
  P(r"\int_{0}^{\frac{\pi}{3}}\tan^{2}x\,dx", "sqrt(3)-pi/3", r"\sqrt3-\frac{\pi}{3}", "tan(x)**2", ("d", "0", "pi/3"), [r"\tan^{2}x=\sec^{2}x-1", r"\left[\tan x-x\right]_{0}^{\frac{\pi}{3}}=\sqrt3-\frac{\pi}{3}"], "$\\tan^{2}x=\\sec^{2}x-1$.", "$\\tan^{2}x=\\sec^{2}x-1$"),
  P(r"\int\sin^{2}x\cos^{2}x\,dx", "x/8-sin(4x)/32", r"\frac{x}{8}-\frac{\sin4x}{32}+C", "sin(x)**2*cos(x)**2", ("i", "0.1", "1.5"), [r"\sin^{2}x\cos^{2}x=\tfrac14\sin^{2}2x=\tfrac18(1-\cos4x)", r"\frac{x}{8}-\frac{\sin4x}{32}+C"], "$\\sin x\\cos x=\\tfrac12\\sin2x$.", "$\\sin x\\cos x=\\tfrac12\\sin2x$")]),

L("sub", "C", "Integration by substitution", "การอินทิเกรตโดยการแทนค่า",
 [T("<b>Theorem (substitution).</b> Let $g:[a,b]\\to\\mathbb{R}$ be continuously differentiable, and $f$ continuous on an interval $J$ containing $g([a,b])$. Then $$\\int_{a}^{b}f\\big(g(x)\\big)\\,g'(x)\\,dx=\\int_{g(a)}^{g(b)}f(u)\\,du.$$",
    "<b>ทฤษฎีบท (การแทนค่า)</b> ให้ $g:[a,b]\\to\\mathbb{R}$ หาอนุพันธ์ได้ต่อเนื่อง และ $f$ ต่อเนื่องบนช่วง $J$ ที่มี $g([a,b])$ แล้ว $$\\int_{a}^{b}f\\big(g(x)\\big)\\,g'(x)\\,dx=\\int_{g(a)}^{g(b)}f(u)\\,du$$"),
  T("Read right to left it is the <b>inverse substitution</b> $x=\\varphi(t)$: $\\int_{\\varphi(\\alpha)}^{\\varphi(\\beta)}f(x)\\,dx=\\int_{\\alpha}^{\\beta}f(\\varphi(t))\\varphi'(t)\\,dt$. Note that $g$ need not be one-to-one.",
    "อ่านจากขวาไปซ้ายคือ <b>การแทนค่าผกผัน</b> $x=\\varphi(t)$: $\\int_{\\varphi(\\alpha)}^{\\varphi(\\beta)}f(x)\\,dx=\\int_{\\alpha}^{\\beta}f(\\varphi(t))\\varphi'(t)\\,dt$ สังเกตว่า $g$ ไม่จำเป็นต้องเป็นหนึ่งต่อหนึ่ง")],
 [S("$f$ is continuous on the interval $J$, so by FTC (1) (lesson 4) it has an antiderivative $F$ on $J$, e.g. $F(u)=\\int_{c}^{u}f$ for a fixed $c\\in J$.", "$f$ ต่อเนื่องบนช่วง $J$ จาก FTC (1) (บทที่ 4) จึงมีปฏิยานุพันธ์ $F$ บน $J$ เช่น $F(u)=\\int_{c}^{u}f$ สำหรับ $c\\in J$ คงที่"),
  S("By the chain rule, for $x\\in[a,b]$,", "จากกฎลูกโซ่ สำหรับ $x\\in[a,b]$", "\\frac{d}{dx}F\\big(g(x)\\big)=f\\big(g(x)\\big)\\,g'(x),"),
  S("which is continuous (a product of continuous functions). So by FTC (2), applied once on each side:", "ซึ่งต่อเนื่อง (ผลคูณของฟังก์ชันต่อเนื่อง) ดังนั้นใช้ FTC (2) ทั้งสองข้าง:", "\\int_{a}^{b}f(g(x))g'(x)\\,dx=F(g(b))-F(g(a))=\\int_{g(a)}^{g(b)}f(u)\\,du.\\ \\blacksquare")],
 [X(r"\int_{1}^{2}x(x-1)^{5}\,dx", "13/42", r"\frac{13}{42}", "x*(x-1)**5", ("d", "1", "2"), [r"u=x-1,\ du=dx,\ x=u+1;\ x:1\to2\Rightarrow u:0\to1", r"\int_{0}^{1}(u+1)u^{5}\,du=\frac17+\frac16=\frac{13}{42}"]),
  X(r"\int_{0}^{3}\frac{x}{\sqrt{x+1}}\,dx", "8/3", r"\frac83", "x/sqrt(x+1)", ("d", "0", "3"), [r"u=x+1:\ \int_{1}^{4}\frac{u-1}{\sqrt u}\,du", r"=\left[\tfrac23u^{\frac32}-2u^{\frac12}\right]_{1}^{4}=\left(\tfrac{16}{3}-4\right)-\left(\tfrac23-2\right)=\frac83"])],
 [P(r"\int_{0}^{1}x(1-x)^{4}\,dx", "1/30", r"\frac{1}{30}", "x*(1-x)**4", ("d", "0", "1"), [r"u=1-x:\ \int_{0}^{1}(1-u)u^{4}\,du", r"=\frac15-\frac16=\frac{1}{30}"], "Let $u=1-x$; the limits swap and $du=-dx$.", "ให้ $u=1-x$ ขอบเขตสลับกันและ $du=-dx$"),
  P(r"\int_{0}^{4}x\sqrt{2x+1}\,dx", "298/15", r"\frac{298}{15}", "x*sqrt(2*x+1)", ("d", "0", "4"), [r"u=2x+1,\ x=\tfrac{u-1}{2},\ dx=\tfrac{du}{2}", r"\tfrac14\int_{1}^{9}\left(u^{\frac32}-u^{\frac12}\right)du=\tfrac14\left[\tfrac25u^{\frac52}-\tfrac23u^{\frac32}\right]_{1}^{9}", r"=\tfrac14\left(\tfrac{396}{5}+\tfrac{4}{15}\right)=\frac{298}{15}"], "Let $u=2x+1$ and change the limits to $1$ and $9$.", "ให้ $u=2x+1$ และเปลี่ยนขอบเขตเป็น $1$ และ $9$"),
  P(r"\int_{1}^{e}\frac{(\ln x)^{2}}{x}\,dx", "1/3", r"\frac13", "log(x)**2/x", ("d", "1", "e"), [r"u=\ln x,\ du=\tfrac{dx}{x}", r"\int_{0}^{1}u^{2}\,du=\frac13"], "Let $u=\\ln x$.", "ให้ $u=\\ln x$"),
  P(r"\int_{0}^{1}\frac{1}{1+\sqrt x}\,dx", "2-2ln(2)", r"2-2\ln2", "1/(1+sqrt(x))", ("d", "0", "1"), [r"x=u^{2},\ dx=2u\,du", r"\int_{0}^{1}\frac{2u}{1+u}\,du=2\left[u-\ln(1+u)\right]_{0}^{1}=2-2\ln2"], "Let $x=u^{2}$ (inverse substitution) to remove the root.", "ให้ $x=u^{2}$ (แทนค่าผกผัน) เพื่อกำจัดราก"),
  P(r"\int_{2}^{5}\frac{x}{\sqrt{x-1}}\,dx", "20/3", r"\frac{20}{3}", "x/sqrt(x-1)", ("d", "2", "5"), [r"u=x-1:\ \int_{1}^{4}\frac{u+1}{\sqrt u}\,du", r"=\left[\tfrac23u^{\frac32}+2u^{\frac12}\right]_{1}^{4}=\left(\tfrac{16}{3}+4\right)-\left(\tfrac23+2\right)=\frac{20}{3}"], "Let $u=x-1$, so $x=u+1$.", "ให้ $u=x-1$ ดังนั้น $x=u+1$")]),

L("parts", "C", "Integration by parts", "การอินทิเกรตทีละส่วน",
 [T("<b>Theorem (integration by parts).</b> Let $u$ and $v$ be continuously differentiable on $[a,b]$. Then $$\\int_{a}^{b}u\\,v'\\,dx=\\Big[uv\\Big]_{a}^{b}-\\int_{a}^{b}u'\\,v\\,dx,$$ and on any interval $\\int uv'\\,dx=uv-\\int u'v\\,dx$.",
    "<b>ทฤษฎีบท (การอินทิเกรตทีละส่วน)</b> ให้ $u$ และ $v$ หาอนุพันธ์ได้ต่อเนื่องบน $[a,b]$ แล้ว $$\\int_{a}^{b}u\\,v'\\,dx=\\Big[uv\\Big]_{a}^{b}-\\int_{a}^{b}u'\\,v\\,dx$$ และบนช่วงใด ๆ $\\int uv'\\,dx=uv-\\int u'v\\,dx$"),
  T("Choosing $u$: take the factor that gets simpler when differentiated (L-I-A-T-E: logs, inverse trig, algebraic, trig, exponential). <b>Cyclic case:</b> if parts twice gives $I=A-kI$ with $k\\neq-1$, then $I=\\dfrac{A}{1+k}$.",
    "การเลือก $u$: เลือกตัวที่ง่ายขึ้นเมื่อหาอนุพันธ์ (L-I-A-T-E: ลอการิทึม, ตรีโกณผกผัน, พีชคณิต, ตรีโกณ, เลขชี้กำลัง) <b>กรณีวนกลับ:</b> ถ้าทำสองครั้งแล้วได้ $I=A-kI$ โดย $k\\neq-1$ จะได้ $I=\\dfrac{A}{1+k}$")],
 [S("By the product rule,", "จากกฎผลคูณ", "(uv)'=u'v+uv',"),
  S("and both $u'v$ and $uv'$ are continuous on $[a,b]$, so they are integrable and FTC (2) applies to $uv$:", "และ $u'v$, $uv'$ ต่อเนื่องบน $[a,b]$ จึงอินทิเกรตได้ และใช้ FTC (2) กับ $uv$ ได้:", "\\Big[uv\\Big]_{a}^{b}=\\int_{a}^{b}(uv)'\\,dx=\\int_{a}^{b}u'v\\,dx+\\int_{a}^{b}uv'\\,dx."),
  S("Rearrange (linearity). The indefinite form is the same identity for antiderivatives. For the cyclic case, $I=A-kI$ gives $(1+k)I=A$ and we divide because $1+k\\neq0$. $\\blacksquare$", "จัดรูป (ความเป็นเชิงเส้น) รูปไม่จำกัดเขตคือเอกลักษณ์เดียวกันสำหรับปฏิยานุพันธ์ กรณีวนกลับ $I=A-kI$ ให้ $(1+k)I=A$ และหารได้เพราะ $1+k\\neq0$ $\\blacksquare$")],
 [X(r"\int x\cos x\,dx", "x sin(x)+cos(x)", r"x\sin x+\cos x+C", "x*cos(x)", ("i", "0", "2"), [r"u=x,\ v'=\cos x:\ u'=1,\ v=\sin x", r"x\sin x-\int\sin x\,dx=x\sin x+\cos x+C"]),
  X(r"\int e^{x}\sin x\,dx", "e^x(sin(x)-cos(x))/2", r"\frac{e^{x}(\sin x-\cos x)}{2}+C", "exp(x)*sin(x)", ("i", "0", "2"), [r"I=e^{x}\sin x-\int e^{x}\cos x\,dx", r"=e^{x}\sin x-\left(e^{x}\cos x+\int e^{x}\sin x\,dx\right)", r"I=e^{x}(\sin x-\cos x)-I\Rightarrow I=\frac{e^{x}(\sin x-\cos x)}{2}+C"])],
 [P(r"\int_{0}^{1}xe^{2x}\,dx", "(e^2+1)/4", r"\frac{e^{2}+1}{4}", "x*exp(2*x)", ("d", "0", "1"), [r"u=x,\ v=\tfrac12e^{2x}", r"\left[\tfrac{x}{2}e^{2x}-\tfrac14e^{2x}\right]_{0}^{1}=\frac{e^{2}}{4}+\frac14"], "$u=x$, $v'=e^{2x}$.", "$u=x$, $v'=e^{2x}$"),
  P(r"\int_{1}^{e}x^{2}\ln x\,dx", "(2e^3+1)/9", r"\frac{2e^{3}+1}{9}", "x**2*log(x)", ("d", "1", "e"), [r"u=\ln x,\ v=\tfrac{x^{3}}{3}", r"\left[\tfrac{x^{3}}{3}\ln x-\tfrac{x^{3}}{9}\right]_{1}^{e}=\frac{e^{3}}{3}-\frac{e^{3}}{9}+\frac19"], "Logs first: $u=\\ln x$.", "เลือกลอการิทึมเป็น $u=\\ln x$"),
  P(r"\int_{0}^{\frac{\pi}{2}}x\cos x\,dx", "pi/2-1", r"\frac{\pi}{2}-1", "x*cos(x)", ("d", "0", "pi/2"), [r"\left[x\sin x+\cos x\right]_{0}^{\frac{\pi}{2}}=\frac{\pi}{2}-1"], "Same as the first example.", "เหมือนตัวอย่างแรก"),
  P(r"\int_{0}^{1}x^{2}e^{x}\,dx", "e-2", r"e-2", "x**2*exp(x)", ("d", "0", "1"), [r"\text{Parts twice: }\int x^{2}e^{x}dx=e^{x}\left(x^{2}-2x+2\right)", r"\left[e^{x}\left(x^{2}-2x+2\right)\right]_{0}^{1}=e-2"], "Use parts twice with $u=x^{2}$, then $u=x$.", "ทำสองครั้ง: $u=x^{2}$ แล้ว $u=x$"),
  P(r"\int_{0}^{\frac{\pi}{2}}e^{x}\cos x\,dx", "(e^(pi/2)-1)/2", r"\frac{e^{\frac{\pi}{2}}-1}{2}", "exp(x)*cos(x)", ("d", "0", "pi/2"), [r"\text{Cyclic: }\int e^{x}\cos x\,dx=\frac{e^{x}(\sin x+\cos x)}{2}", r"\frac{e^{\frac{\pi}{2}}(1+0)-(0+1)}{2}"], "Cyclic: parts twice, then solve for $I$.", "วนกลับ: ทำสองครั้งแล้วแก้หา $I$")]),

L("pf", "C", "Partial fractions", "เศษส่วนย่อย",
 [T("<b>Theorem.</b> Let $P$, $Q$ be real polynomials with $\\deg P<\\deg Q$ and $$Q(x)=c\\prod_{i}(x-a_i)^{m_i}\\prod_{j}\\left(x^{2}+b_jx+c_j\\right)^{n_j},$$ with distinct $a_i$ and distinct irreducible quadratics ($b_j^{2}<4c_j$). Then there are unique real constants with $$\\frac{P}{Q}=\\sum_{i}\\sum_{k=1}^{m_i}\\frac{A_{ik}}{(x-a_i)^{k}}+\\sum_{j}\\sum_{k=1}^{n_j}\\frac{B_{jk}x+C_{jk}}{\\left(x^{2}+b_jx+c_j\\right)^{k}}.$$",
    "<b>ทฤษฎีบท</b> ให้ $P$, $Q$ เป็นพหุนามจริงที่ $\\deg P<\\deg Q$ และ $$Q(x)=c\\prod_{i}(x-a_i)^{m_i}\\prod_{j}\\left(x^{2}+b_jx+c_j\\right)^{n_j}$$ โดย $a_i$ ต่างกันและพหุนามกำลังสองลดทอนไม่ได้ต่างกัน ($b_j^{2}<4c_j$) แล้วมีค่าคงตัวจริงเพียงชุดเดียวที่ $$\\frac{P}{Q}=\\sum_{i}\\sum_{k=1}^{m_i}\\frac{A_{ik}}{(x-a_i)^{k}}+\\sum_{j}\\sum_{k=1}^{n_j}\\frac{B_{jk}x+C_{jk}}{\\left(x^{2}+b_jx+c_j\\right)^{k}}$$"),
  T("If $\\deg P\\ge\\deg Q$, divide first: $P=SQ+R$ with $\\deg R<\\deg Q$, so $\\dfrac PQ=S+\\dfrac RQ$.", "ถ้า $\\deg P\\ge\\deg Q$ ให้หารก่อน: $P=SQ+R$ โดย $\\deg R<\\deg Q$ ดังนั้น $\\dfrac PQ=S+\\dfrac RQ$")],
 [S("<b>Lemma (Bézout).</b> If polynomials $Q_1$, $Q_2$ have no common non-constant factor, the Euclidean algorithm gives polynomials $s$, $t$ with", "<b>บทตั้ง (Bézout)</b> ถ้าพหุนาม $Q_1$, $Q_2$ ไม่มีตัวประกอบร่วมที่ไม่ใช่ค่าคงตัว ขั้นตอนวิธีแบบยุคลิดให้พหุนาม $s$, $t$ ที่", "s\\,Q_1+t\\,Q_2=1."),
  S("<b>Splitting.</b> Then $\\dfrac{P}{Q_1Q_2}=\\dfrac{P(sQ_1+tQ_2)}{Q_1Q_2}=\\dfrac{Pt}{Q_1}+\\dfrac{Ps}{Q_2}$. Divide: $Pt=\\alpha Q_1+A$, $Ps=\\beta Q_2+B$ with $\\deg A<\\deg Q_1$, $\\deg B<\\deg Q_2$:", "<b>การแยก</b> จะได้ $\\dfrac{P}{Q_1Q_2}=\\dfrac{P(sQ_1+tQ_2)}{Q_1Q_2}=\\dfrac{Pt}{Q_1}+\\dfrac{Ps}{Q_2}$ หาร: $Pt=\\alpha Q_1+A$, $Ps=\\beta Q_2+B$ โดย $\\deg A<\\deg Q_1$, $\\deg B<\\deg Q_2$:", "\\frac{P}{Q_1Q_2}=\\frac{A}{Q_1}+\\frac{B}{Q_2}+(\\alpha+\\beta)."),
  S("As $x\\to\\infty$ every fraction here tends to $0$ (degree of top less than bottom), so the polynomial $\\alpha+\\beta$ tends to $0$, hence is the zero polynomial.", "เมื่อ $x\\to\\infty$ ทุกเศษส่วนในที่นี้เข้าใกล้ $0$ (ดีกรีตัวเศษน้อยกว่าตัวส่วน) ดังนั้นพหุนาม $\\alpha+\\beta$ เข้าใกล้ $0$ จึงเป็นพหุนามศูนย์"),
  S("<b>Repeat</b> this on the distinct prime-power factors $(x-a_i)^{m_i}$ and $(x^{2}+b_jx+c_j)^{n_j}$, which are pairwise coprime.", "<b>ทำซ้ำ</b> กับตัวประกอบกำลังเฉพาะ $(x-a_i)^{m_i}$ และ $(x^{2}+b_jx+c_j)^{n_j}$ ที่เป็นจำนวนเฉพาะสัมพัทธ์กันทีละคู่"),
  S("<b>One prime power.</b> For $\\dfrac{A}{(x-a)^{m}}$ with $\\deg A<m$, expand $A$ in powers of $x-a$ (Taylor's formula for polynomials):", "<b>กำลังเฉพาะตัวเดียว</b> สำหรับ $\\dfrac{A}{(x-a)^{m}}$ ที่ $\\deg A<m$ กระจาย $A$ ในกำลังของ $x-a$ (สูตรเทย์เลอร์ของพหุนาม):", "A(x)=\\sum_{k=0}^{m-1}d_k(x-a)^{k}\\ \\Rightarrow\\ \\frac{A}{(x-a)^{m}}=\\sum_{k=0}^{m-1}\\frac{d_k}{(x-a)^{m-k}}."),
  S("For a quadratic power, divide $A$ repeatedly by $q=x^{2}+bx+c$: $A=\\sum_k r_k q^{k}$ with each $\\deg r_k\\le1$, giving terms $\\dfrac{r_k}{q^{n-k}}$.", "สำหรับกำลังของพหุนามกำลังสอง หาร $A$ ด้วย $q=x^{2}+bx+c$ ซ้ำ ๆ: $A=\\sum_k r_k q^{k}$ โดย $\\deg r_k\\le1$ ได้พจน์ $\\dfrac{r_k}{q^{n-k}}$"),
  S("<b>Uniqueness.</b> The difference of two decompositions is a decomposition of $0$. Multiply by $(x-a_i)^{m_i}$ and let $x\\to a_i$: the top coefficient $A_{im_i}$ must be $0$; repeat downwards. For a quadratic factor do the same at one of its complex roots $z$ (with $B,C$ real, $Bz+C=0$ forces $B=C=0$ since $z\\notin\\mathbb{R}$). $\\blacksquare$", "<b>ความเป็นหนึ่งเดียว</b> ผลต่างของการแยกสองแบบคือการแยกของ $0$ คูณด้วย $(x-a_i)^{m_i}$ แล้วให้ $x\\to a_i$: สัมประสิทธิ์บนสุด $A_{im_i}$ ต้องเป็น $0$ ทำซ้ำลงมา สำหรับตัวประกอบกำลังสองทำเช่นเดียวกันที่รากเชิงซ้อน $z$ ตัวหนึ่ง ($B,C$ จริงและ $Bz+C=0$ บังคับให้ $B=C=0$ เพราะ $z\\notin\\mathbb{R}$) $\\blacksquare$")],
 [X(r"\int\frac{5x+1}{(x-1)(x+2)}\,dx", "2ln(x-1)+3ln(x+2)", r"2\ln|x-1|+3\ln|x+2|+C", "(5*x+1)/((x-1)*(x+2))", ("i", "1.5", "3"), [r"\frac{5x+1}{(x-1)(x+2)}=\frac{A}{x-1}+\frac{B}{x+2}", r"x=1:\ A=\tfrac63=2;\quad x=-2:\ B=\tfrac{-9}{-3}=3", r"2\ln|x-1|+3\ln|x+2|+C"]),
  X(r"\int_{1}^{2}\frac{1}{x^{2}(x+1)}\,dx", "ln(3/4)+1/2", r"\ln\frac34+\frac12", "1/(x**2*(x+1))", ("d", "1", "2"), [r"\frac{1}{x^{2}(x+1)}=-\frac1x+\frac{1}{x^{2}}+\frac{1}{x+1}", r"\left[-\ln x-\tfrac1x+\ln(x+1)\right]_{1}^{2}=\ln3-2\ln2+\frac12"])],
 [P(r"\int_{0}^{1}\frac{1}{(x+1)(x+2)}\,dx", "ln(4/3)", r"\ln\frac43", "1/((x+1)*(x+2))", ("d", "0", "1"), [r"\frac{1}{x+1}-\frac{1}{x+2}", r"\left[\ln\frac{x+1}{x+2}\right]_{0}^{1}=\ln\tfrac23-\ln\tfrac12=\ln\frac43"], "Cover-up: put $x=-1$, then $x=-2$.", "ปิดตัวประกอบ: แทน $x=-1$ แล้ว $x=-2$"),
  P(r"\int_{2}^{4}\frac{x+5}{x^{2}-1}\,dx", "ln(243/25)", r"\ln\frac{243}{25}", "(x+5)/(x**2-1)", ("d", "2", "4"), [r"\frac{x+5}{(x-1)(x+1)}=\frac{3}{x-1}-\frac{2}{x+1}", r"\left[3\ln(x-1)-2\ln(x+1)\right]_{2}^{4}=3\ln3-2\ln\tfrac53=\ln\frac{243}{25}"], "Factorise $x^{2}-1$ first.", "แยกตัวประกอบ $x^{2}-1$ ก่อน"),
  P(r"\int_{1}^{2}\frac{x^{2}+1}{x(x+1)}\,dx", "1+ln(8/9)", r"1+\ln\frac89", "(x**2+1)/(x*(x+1))", ("d", "1", "2"), [r"\frac{x^{2}+1}{x^{2}+x}=1+\frac{1-x}{x(x+1)}=1+\frac1x-\frac{2}{x+1}", r"\left[x+\ln x-2\ln(x+1)\right]_{1}^{2}=1+\ln2-2\ln\tfrac32=1+\ln\frac89"], "Improper: divide first.", "เศษเกิน: หารก่อน"),
  P(r"\int_{0}^{1}\frac{x}{(x+1)^{2}}\,dx", "ln(2)-1/2", r"\ln2-\frac12", "x/(x+1)**2", ("d", "0", "1"), [r"\frac{x}{(x+1)^{2}}=\frac{1}{x+1}-\frac{1}{(x+1)^{2}}", r"\left[\ln(x+1)+\tfrac{1}{x+1}\right]_{0}^{1}=\ln2+\tfrac12-1"], "Repeated factor: $\\frac{A}{x+1}+\\frac{B}{(x+1)^{2}}$.", "ตัวประกอบซ้ำ: $\\frac{A}{x+1}+\\frac{B}{(x+1)^{2}}$"),
  P(r"\int\frac{3x+5}{(x+1)(x+3)}\,dx", "ln(x+1)+2ln(x+3)", r"\ln|x+1|+2\ln|x+3|+C", "(3*x+5)/((x+1)*(x+3))", ("i", "0", "2"), [r"x=-1:\ A=\tfrac22=1;\quad x=-3:\ B=\tfrac{-4}{-2}=2", r"\ln|x+1|+2\ln|x+3|+C"], "Cover-up at $x=-1$ and $x=-3$.", "ปิดตัวประกอบที่ $x=-1$ และ $x=-3$")]),

L("trap", "C", "The trapezium rule and its error", "กฎสี่เหลี่ยมคางหมูและความคลาดเคลื่อน",
 [T("<b>Theorem.</b> Let $f$ be twice continuously differentiable on $[a,b]$, $h=\\frac{b-a}{n}$, $x_i=a+ih$, and $$T_n=\\frac h2\\Big[f(x_0)+2\\big(f(x_1)+\\dots+f(x_{n-1})\\big)+f(x_n)\\Big].$$ Then for some $\\xi\\in(a,b)$, $$\\int_{a}^{b}f(x)\\,dx=T_n-\\frac{(b-a)h^{2}}{12}f''(\\xi).$$",
    "<b>ทฤษฎีบท</b> ให้ $f$ หาอนุพันธ์อันดับสองได้ต่อเนื่องบน $[a,b]$, $h=\\frac{b-a}{n}$, $x_i=a+ih$ และ $$T_n=\\frac h2\\Big[f(x_0)+2\\big(f(x_1)+\\dots+f(x_{n-1})\\big)+f(x_n)\\Big]$$ แล้วมี $\\xi\\in(a,b)$ ที่ $$\\int_{a}^{b}f(x)\\,dx=T_n-\\frac{(b-a)h^{2}}{12}f''(\\xi)$$"),
  T("So if $f''>0$ (convex) the rule <b>overestimates</b>, and $|\\text{error}|\\le\\dfrac{(b-a)h^{2}}{12}\\max|f''|$.", "ดังนั้นถ้า $f''>0$ (เว้าขึ้น) กฎนี้ให้ค่า<b>เกิน</b> และ $|\\text{error}|\\le\\dfrac{(b-a)h^{2}}{12}\\max|f''|$")],
 [S("One strip, moved to $[0,h]$: let $g$ be $C^{2}$ on $[0,h]$ and $K(x)=\\tfrac12x(x-h)$, so $K(0)=K(h)=0$, $K'=x-\\tfrac h2$, $K''=1$. Integrate by parts twice:", "แถบเดียว เลื่อนไปที่ $[0,h]$: ให้ $g$ เป็น $C^{2}$ บน $[0,h]$ และ $K(x)=\\tfrac12x(x-h)$ จะได้ $K(0)=K(h)=0$, $K'=x-\\tfrac h2$, $K''=1$ อินทิเกรตทีละส่วนสองครั้ง:", "\\int_{0}^{h}Kg''\\,dx=\\Big[Kg'\\Big]_{0}^{h}-\\int_{0}^{h}\\left(x-\\tfrac h2\\right)g'\\,dx=-\\Big[\\left(x-\\tfrac h2\\right)g\\Big]_{0}^{h}+\\int_{0}^{h}g\\,dx."),
  S("The bracket equals $\\tfrac h2\\big(g(0)+g(h)\\big)$, so", "วงเล็บเท่ากับ $\\tfrac h2\\big(g(0)+g(h)\\big)$ ดังนั้น", "\\int_{0}^{h}g\\,dx=\\frac h2\\big(g(0)+g(h)\\big)+\\int_{0}^{h}K(x)g''(x)\\,dx."),
  S("$K\\le0$ on $[0,h]$ and $g''$ is continuous, so the weighted mean value theorem for integrals (proved like lesson 4, using $m\\,K\\ge Kg''\\ge M\\,K$) gives $\\eta\\in[0,h]$ with", "$K\\le0$ บน $[0,h]$ และ $g''$ ต่อเนื่อง ทฤษฎีบทค่าเฉลี่ยถ่วงน้ำหนักสำหรับอินทิกรัล (พิสูจน์แบบบทที่ 4 โดยใช้ $m\\,K\\ge Kg''\\ge M\\,K$) ให้ $\\eta\\in[0,h]$ ที่", "\\int_{0}^{h}Kg''\\,dx=g''(\\eta)\\int_{0}^{h}\\tfrac12x(x-h)\\,dx=-\\frac{h^{3}}{12}g''(\\eta)."),
  S("Add over the $n$ strips:", "รวมทั้ง $n$ แถบ:", "\\int_{a}^{b}f=T_n-\\frac{h^{3}}{12}\\sum_{i=1}^{n}f''(\\eta_i)=T_n-\\frac{nh^{3}}{12}\\cdot\\frac1n\\sum_{i=1}^{n}f''(\\eta_i)."),
  S("The average $\\frac1n\\sum f''(\\eta_i)$ lies between $\\min f''$ and $\\max f''$, so by the intermediate value theorem it equals $f''(\\xi)$ for some $\\xi$. Finally $nh^{3}=(b-a)h^{2}$. $\\blacksquare$", "ค่าเฉลี่ย $\\frac1n\\sum f''(\\eta_i)$ อยู่ระหว่าง $\\min f''$ และ $\\max f''$ จากทฤษฎีบทค่าระหว่างกลางจึงเท่ากับ $f''(\\xi)$ สำหรับบาง $\\xi$ และ $nh^{3}=(b-a)h^{2}$ $\\blacksquare$")],
 [X(r"T_2\text{ for }\int_{0}^{1}x^{2}\,dx", "3/8", r"\frac38", "0", ("v", "mpf(3)/8"), [r"h=\tfrac12:\ T_2=\tfrac14\left[0+2\cdot\tfrac14+1\right]=\frac38", r"\text{Error: }-\tfrac{1\cdot\frac14}{12}\cdot2=-\tfrac{1}{24},\ \text{and }\tfrac38-\tfrac1{24}=\tfrac13\ \checkmark"]),
  X(r"T_4\text{ for }\int_{0}^{1}x^{2}\,dx", "11/32", r"\frac{11}{32}", "0", ("v", "mpf(11)/32"), [r"h=\tfrac14:\ \tfrac18\left[0+2\left(\tfrac1{16}+\tfrac14+\tfrac9{16}\right)+1\right]=\frac{11}{32}", r"\text{Overestimate by }\tfrac{1}{96}\text{ since }f''=2>0"])],
 [P(r"\text{Trapezium rule, 2 strips: }\int_{1}^{3}\frac1x\,dx", "7/6", r"\frac76", "0", ("v", "mpf(7)/6"), [r"h=1:\ \tfrac12\left[1+2\cdot\tfrac12+\tfrac13\right]=\frac76"], "$h=1$; the $x$-values are $1,2,3$.", "$h=1$ ค่า $x$ คือ $1,2,3$"),
  P(r"\text{Trapezium rule, 4 strips: }\int_{0}^{2}e^{x}\,dx\ \text{(4 d.p.)}", "6.5216", r"\tfrac14\left[1+2\left(e^{\frac12}+e+e^{\frac32}\right)+e^{2}\right]\approx6.5216", "0", ("n", "(1+2*(exp(0.5)+e+exp(1.5))+e**2)/4", "2e-5"), [r"h=\tfrac12:\ \tfrac14\left[e^{0}+2\left(e^{\frac12}+e^{1}+e^{\frac32}\right)+e^{2}\right]", r"\approx6.5216"], "$h=\\tfrac12$; the $x$-values are $0,\\tfrac12,1,\\tfrac32,2$.", "$h=\\tfrac12$ ค่า $x$ คือ $0,\\tfrac12,1,\\tfrac32,2$"),
  P(r"\text{For }\int_{0}^{2}x^{3}\,dx\text{ with 2 strips, find }T_2-\text{exact}", "1", r"1", "0", ("v", "1"), [r"T_2=\tfrac12\left[0+2\cdot1+8\right]=5", r"\int_{0}^{2}x^{3}dx=4,\ \text{so }T_2-4=1"], "Work out $T_2$ and the exact value separately.", "คำนวณ $T_2$ และค่าจริงแยกกัน"),
  P(r"\text{Error bound }\tfrac{(b-a)h^{2}}{12}\max|f''|\le10^{-4}\text{ for }\int_{0}^{1}e^{x}dx.\ \text{Smallest }n?", "48", r"48", "0", ("v", "48"), [r"f''=e^{x}\le e,\ h=\tfrac1n:\ \frac{e}{12n^{2}}\le10^{-4}", r"n^{2}\ge\frac{e}{0.0012}\approx2265.2\Rightarrow n\ge47.6", r"n=48"], "Solve $\\frac{e}{12n^{2}}\\le10^{-4}$ for $n$.", "แก้ $\\frac{e}{12n^{2}}\\le10^{-4}$ หา $n$"),
  P(r"\text{Trapezium rule, 4 strips: }\int_{0}^{1}x^{3}\,dx", "17/64", r"\frac{17}{64}", "0", ("v", "mpf(17)/64"), [r"h=\tfrac14:\ \tfrac18\left[0+2\left(\tfrac1{64}+\tfrac8{64}+\tfrac{27}{64}\right)+1\right]", r"=\tfrac18\cdot\tfrac{136}{64}=\frac{17}{64}"], "$h=\\tfrac14$: cube $\\tfrac14,\\tfrac12,\\tfrac34$.", "$h=\\tfrac14$: ยกกำลังสาม $\\tfrac14,\\tfrac12,\\tfrac34$")]),
]
